// Google News RSS sau XML node: $json.rss.channel.item là array
const feedItems = $json?.rss?.channel?.item ?? [];

// lấy metadata của stock từ item trước đó (Split Out Items)
const stock = $item(0).$node["04 - For Each Symbol (Split Items)"].json; 
// Nếu node split của bạn tên khác, đổi "Split Out Items" đúng tên node.

return feedItems.map(it => ({
  json: {
    scope: "stocks",
    topic: stock.symbol,
    symbol: stock.symbol,
    name: stock.name,
    exchange: stock.exchange,

    title: it.title,
    url: typeof it.link === "string" ? it.link : it.link?.[0] ?? "",
    published_at_raw: it.pubDate,
    published_at: it.pubDate ? new Date(it.pubDate).toISOString() : null,

    source: it.source?._ ?? it.source ?? "google_news",
  }
}));

// n8n Code node (JavaScript)
// Expect each item is a news item and ALSO contains workflow_state.value as last_run_at.
// Fields used: json.published_at (ISO), json.symbol, json.value (last_run_at)
// Output: filtered, sorted desc, limited 10 per symbol.

const input = $input.all();
if (input.length === 0) return [];

// Find last_run_at from any item (after merge it should exist on all items)
const lastRunRaw = input.find(i => i.json?.value)?.json?.value;
const from = lastRunRaw ? new Date(lastRunRaw) : null;
const to = new Date(); // now

const isValidDate = (d) => d instanceof Date && !isNaN(d.getTime());

// Hard cap 30 days
const thirtyDaysAgo = new Date(to.getTime() - 30 * 24 * 60 * 60 * 1000);

// windowFrom = max(last_run_at, thirtyDaysAgo) (fallback if last_run_at invalid)
const windowFrom = (from && isValidDate(from))
  ? new Date(Math.max(from.getTime(), thirtyDaysAgo.getTime()))
  : thirtyDaysAgo;

const windowTo = to;

// Parse + filter
const parsed = input
  .map(i => {
    const pub = new Date(i.json.published_at);
    return {
      item: i,
      pub,
      ok: isValidDate(pub),
    };
  })
  .filter(x => x.ok && x.pub > windowFrom && x.pub <= windowTo);

// Sort desc by published_at
parsed.sort((a, b) => b.pub.getTime() - a.pub.getTime());

// Limit per symbol
const MAX_PER_SYMBOL = 10;
const count = new Map();
const out = [];

for (const x of parsed) {
  const sym = x.item.json.symbol || 'UNKNOWN';
  const c = count.get(sym) || 0;
  if (c >= MAX_PER_SYMBOL) continue;

  count.set(sym, c + 1);

  // Attach window info for debugging/downstream
  x.item.json.window_from = windowFrom.toISOString();
  x.item.json.window_to = windowTo.toISOString();

  out.push(x.item);
}

return out;

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const chr = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + chr;
    hash |= 0; // convert to 32bit int
  }
  return hash.toString();
}

return $input.all().map(item => {
  const url = item.json.url || '';
  item.json.hash = simpleHash(url);
  return item;
});

// Remove empty objects {} from Data Table lookup output
const items = $input.all();

const cleaned = items.filter(i => {
  const j = i.json ?? {};
  return Object.keys(j).length > 0;  // keep only non-empty rows
});

return cleaned;

