// Lấy toàn bộ items
const items = $input.all();

// Nhóm theo topic (mã cổ phiếu)
const grouped = {};

for (const item of items) {
  const news = item.json;
  const topic = news.topic || "UNKNOWN";

  if (!grouped[topic]) {
    grouped[topic] = [];
  }

  grouped[topic].push({
    title: news.title,
    source: news.source,
    published_at: news.published_at,
    url: news.url
  });
}

// Build text block cho AI
let formattedText = "";

for (const [symbol, articles] of Object.entries(grouped)) {
  formattedText += `\n\nMã cổ phiếu: ${symbol}\n`;

  articles.forEach((a, index) => {
    formattedText += `${index + 1}. ${a.title}\n`;
    formattedText += `   Nguồn: ${a.source}\n`;
    formattedText += `   Link: ${a.url}\n`;
  });
}

// Trả về 1 item duy nhất
return [
  {
    json: {
      ai_input: formattedText
    }
  }
];

const instruction =
  "Bạn là chuyên gia phân tích chứng khoán Việt Nam.\n" +
  "Hãy tổng hợp bản tin theo format Telegram.\n\n" +
  "Yêu cầu:\n" +
  "- Nhóm theo mã cổ phiếu\n" +
  "- Tối đa 5 gạch đầu dòng/mã\n" +
  "- Mỗi gạch đầu dòng: tiêu đề rút gọn + (Tích cực/Trung lập/Tiêu cực) + 1 câu nhận định\n" +
  "- Cuối mỗi gạch đầu dòng kèm nguồn\n" +
  "- Không quá 1200 ký tự\n\n" +
  "Dữ liệu tin:\n";

return [
  {
    json: {
      final_prompt: instruction + $json.ai_input + "\nChỉ trả về nội dung bản tin (không giải thích thêm)."
    }
  }
];

const raw =
  $json?.message?.content ??
  $json?.response ??
  $json?.choices?.[0]?.message?.content ??
  "";

const text = (raw || "").trim();

const header =
  "━━━━━━━━━━━━━━━━━━\n\n" +
  "📊 <b>BẢN TIN CHỨNG KHOÁN</b>\n\n" +
  "━━━━━━━━━━━━━━━━━━\n\n";

const footer = "\n\n━━━━━━━━━━━━━━━━━━";

// No content => no-news template (optional)
if (!text) {
  const noNews =
    header +
    "🕒 <b>KHÔNG CÓ TIN MỚI</b>\n\n" +
    "Không tìm thấy bài viết mới cho các mã trong danh sách theo dõi\n" +
    "trong khoảng thời gian cập nhật gần nhất.\n\n" +
    "✅ Hệ thống đã kiểm tra và sẽ tiếp tục theo dõi." +
    footer;

  return [{ json: { telegram_body: noNews } }];
}

// -------- helpers ----------
const normSent = (s) => {
  const t = (s || "").toLowerCase();
  if (t.includes("tích cực")) return "Tích cực";
  if (t.includes("tiêu cực")) return "Tiêu cực";
  if (t.includes("trung lập")) return "Trung lập";
  return "Trung lập";
};

const iconTitle = (sent) => {
  if (sent === "Tích cực") return "📈 <b>Tích cực</b>";
  if (sent === "Tiêu cực") return "📉 <b>Tiêu cực</b>";
  return "➖ <b>Trung lập</b>";
};

// -------- extract ticker ----------
let ticker = "";

// Format 1: "Mã cổ phiếu: FPT"
let m = text.match(/Mã cổ phiếu:\s*([A-Z0-9.\-]+)/i);
if (m) ticker = m[1].toUpperCase();

// Format 2: "FPT (Tích cực) - ..."
if (!ticker) {
  m = text.match(/^([A-Z0-9.\-]{2,10})\s*\(/);
  if (m) ticker = m[1].toUpperCase();
}

// Format 3: "FPT - Trung lập - ..."
if (!ticker) {
  m = text.match(/^([A-Z0-9.\-]{2,10})\s*-\s*(Tích cực|Trung lập|Tiêu cực)\s*-/i);
  if (m) ticker = m[1].toUpperCase();
}

// fallback
if (!ticker) ticker = "NEWS";

// -------- extract sources ----------
let sources = "";
m = text.match(/Nguồn:\s*(.+)$/i);
if (m) sources = m[1].trim();

// -------- parse items ----------
const pos = [];
const neu = [];
const neg = [];

// Split lines; if only 1 line, still works
const lines = text.split("\n").map(s => s.trim()).filter(Boolean);

// Function to push bullet by sentiment
const pushBySent = (sent, title) => {
  const s = normSent(sent);
  const cleanTitle = (title || "")
    .replace(/\s+Nguồn:\s*.+$/i, "") // strip inline source part
    .trim();

  if (!cleanTitle) return;

  if (s === "Tích cực") pos.push(`• ${cleanTitle}`);
  else if (s === "Tiêu cực") neg.push(`• ${cleanTitle}`);
  else neu.push(`• ${cleanTitle}`);
};

// Try parse each line with multiple patterns
for (let line of lines) {
  // ignore "Nguồn: ..."
  if (/^Nguồn:/i.test(line)) continue;

  // Pattern A: "- <source>: <sent> - <title> ..."
  let mm = line.match(/^-?\s*([^:]+):\s*(Tích cực|Trung lập|Tiêu cực)\s*-\s*(.+)$/i);
  if (mm) {
    const sent = mm[2];
    const title = mm[3];
    pushBySent(sent, title);
    continue;
  }

  // Pattern B: "FPT (Tích cực) - <title> ..."
  mm = line.match(/^[A-Z0-9.\-]{2,10}\s*\((Tích cực|Trung lập|Tiêu cực)\)\s*-\s*(.+)$/i);
  if (mm) {
    const sent = mm[1];
    const title = mm[2];
    pushBySent(sent, title);
    continue;
  }

  // Pattern C: "FPT - Tích cực - <title> ..."
  mm = line.match(/^[A-Z0-9.\-]{2,10}\s*-\s*(Tích cực|Trung lập|Tiêu cực)\s*-\s*(.+)$/i);
  if (mm) {
    const sent = mm[1];
    const title = mm[2];
    pushBySent(sent, title);
    continue;
  }

  // Pattern D: nếu AI trả kiểu "• ..." thì giữ nguyên vào trung lập
  if (line.startsWith("•")) {
    neu.push(line);
    continue;
  }
}

// If nothing parsed, treat whole text (without sources) as one neutral bullet
if (pos.length + neu.length + neg.length === 0) {
  const fallbackTitle = text.replace(/Nguồn:\s*.+$/i, "").trim();
  if (fallbackTitle) neu.push(`• ${fallbackTitle}`);
}

// -------- build message ----------
let body = header + `🏢 <b>${ticker}</b>\n\n`;

if (pos.length) body += `${iconTitle("Tích cực")}\n${pos.join("\n")}\n\n`;
if (neu.length) body += `${iconTitle("Trung lập")}\n${neu.join("\n")}\n\n`;
if (neg.length) body += `${iconTitle("Tiêu cực")}\n${neg.join("\n")}\n\n`;

if (sources) {
  body += `🔎 <b>Nguồn:</b>\n${sources}`;
} else {
  // optional: không bắt buộc phải có
  body = body.trimEnd();
}

body += footer;

return [{ json: { telegram_body: body } }];
